-- 0003_indexes.sql
-- ============================================================
-- Non-PK indexes for the public-schema tables.
-- Most exist to make foreign-key joins cheap; a handful index status / date
-- columns used by the dashboard filters.

CREATE INDEX amenity_bookings_building_idx  ON public.amenity_bookings (building_id);
CREATE INDEX amenity_bookings_date_idx      ON public.amenity_bookings (booking_date);
CREATE INDEX amenity_bookings_resident_idx  ON public.amenity_bookings (resident_profile_id);

CREATE INDEX invoices_resident_idx          ON public.invoices (resident_profile_id);
CREATE INDEX invoices_status_idx            ON public.invoices (status);
CREATE INDEX invoices_unit_idx              ON public.invoices (unit_id);

CREATE INDEX payments_invoice_idx           ON public.payments (invoice_id);

CREATE INDEX resident_assignments_unit_id_idx ON public.resident_assignments (unit_id);

CREATE INDEX resident_documents_profile_idx ON public.resident_documents (profile_id);

CREATE INDEX security_assignments_building_id_idx ON public.security_assignments (building_id);

CREATE INDEX service_requests_resident_idx ON public.service_requests (resident_profile_id);
CREATE INDEX service_requests_status_idx   ON public.service_requests (status);
CREATE INDEX service_requests_unit_idx     ON public.service_requests (unit_id);

CREATE INDEX unit_attachments_unit_id_idx  ON public.unit_attachments (unit_id);

CREATE INDEX units_building_id_idx         ON public.units (building_id);

CREATE INDEX visits_status_idx             ON public.visits (status);
CREATE INDEX visits_unit_id_idx            ON public.visits (unit_id);
CREATE INDEX visits_visit_date_idx         ON public.visits (visit_date);

-- ============================================================
-- 0004_helper_functions.sql
-- ============================================================
-- SECURITY DEFINER helper functions in the `private` schema. RLS policies on
-- public.* tables call these to avoid the infinite-recursion trap you hit when
-- a policy on table X subqueries table Y whose policy in turn subqueries X.
-- All of them are STABLE, run with the function owner's permissions, and have
-- search_path locked to '' so an attacker cannot shadow public tables.

-- --- private schema helpers --------------------------------------------------

CREATE OR REPLACE FUNCTION private.is_resident_of_unit(p_profile_id uuid, p_unit_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE SECURITY DEFINER
SET search_path TO ''
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.resident_assignments
    WHERE profile_id = p_profile_id AND unit_id = p_unit_id
  );
$$;

CREATE OR REPLACE FUNCTION private.is_resident_of_building(p_profile_id uuid, p_building_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE SECURITY DEFINER
SET search_path TO ''
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.resident_assignments ra
    JOIN public.units u ON u.id = ra.unit_id
    WHERE ra.profile_id = p_profile_id AND u.building_id = p_building_id
  );
$$;

CREATE OR REPLACE FUNCTION private.is_security_of_building(p_profile_id uuid, p_building_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE SECURITY DEFINER
SET search_path TO ''
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.security_assignments
    WHERE profile_id = p_profile_id AND building_id = p_building_id
  );
$$;

CREATE OR REPLACE FUNCTION private.security_can_see_resident(p_security_id uuid, p_resident_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE SECURITY DEFINER
SET search_path TO ''
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.resident_assignments ra
    JOIN public.units                u  ON u.id = ra.unit_id
    JOIN public.security_assignments sa ON sa.building_id = u.building_id
    WHERE ra.profile_id = p_resident_id AND sa.profile_id = p_security_id
  );
$$;

CREATE OR REPLACE FUNCTION private.unit_building_id(p_unit_id uuid)
RETURNS uuid
LANGUAGE sql
STABLE SECURITY DEFINER
SET search_path TO ''
AS $$
  SELECT building_id FROM public.units WHERE id = p_unit_id;
$$;

CREATE OR REPLACE FUNCTION private.user_id_by_email(p_email text)
RETURNS uuid
LANGUAGE sql
STABLE SECURITY DEFINER
SET search_path TO ''
AS $$
  SELECT id FROM auth.users WHERE lower(email) = lower(p_email) LIMIT 1;
$$;

-- --- public schema helper ----------------------------------------------------

-- Returns auth.users.email for the given profile IDs, but only when the caller
-- has app_metadata.role = 'pmc'. PostgREST cannot reach auth.users directly, so
-- the PMC admin UI calls this RPC to display resident / guard email addresses.
CREATE OR REPLACE FUNCTION public.get_emails_for_profiles(p_ids uuid[])
RETURNS TABLE(id uuid, email text)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $$
BEGIN
  IF COALESCE((auth.jwt() -> 'app_metadata' ->> 'role'), '') <> 'pmc' THEN
    RETURN;
  END IF;
  RETURN QUERY SELECT u.id, u.email::text FROM auth.users u WHERE u.id = ANY(p_ids);
END;
$$;

-- ============================================================
-- 0005_rls_policies.sql
-- ============================================================
-- Row-Level Security for every public table.
--
-- Naming convention: <role>_<table>_<action>. The PMC role gets full access
-- via a single ALL policy; residents and security see only their own rows
-- (or rows scoped to their assigned unit / building) via the SECURITY DEFINER
-- helpers in the `private` schema.
--
-- Policies key off auth.jwt()->'app_metadata'->>'role' (NOT a subquery against
-- public.profiles) to avoid infinite recursion. When creating an auth.users row,
-- ALWAYS set app_metadata.role — a NULL role hits every PMC policy as 'not pmc'.

-- ---------------------------------------------------------------------------
-- Enable RLS on every table
-- ---------------------------------------------------------------------------
ALTER TABLE public.app_state             ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.buildings             ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.units                 ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.profiles              ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.resident_assignments  ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.security_assignments  ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.visits                ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.unit_attachments      ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.amenity_bookings      ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.service_requests      ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.invoices              ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.payments              ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.resident_documents    ENABLE ROW LEVEL SECURITY;

-- ---------------------------------------------------------------------------
-- app_state — single 'main' row, open to anon + authenticated (legacy)
-- ---------------------------------------------------------------------------
CREATE POLICY "Allow read of main row"
  ON public.app_state FOR SELECT TO anon, authenticated
  USING (id = 'main');

CREATE POLICY "Allow insert of main row"
  ON public.app_state FOR INSERT TO anon, authenticated
  WITH CHECK (id = 'main');

CREATE POLICY "Allow update of main row"
  ON public.app_state FOR UPDATE TO anon, authenticated
  USING (id = 'main') WITH CHECK (id = 'main');

-- ---------------------------------------------------------------------------
-- buildings
-- ---------------------------------------------------------------------------
CREATE POLICY pmc_buildings_all
  ON public.buildings FOR ALL TO authenticated
  USING      ((auth.jwt() -> 'app_metadata' ->> 'role') = 'pmc')
  WITH CHECK ((auth.jwt() -> 'app_metadata' ->> 'role') = 'pmc');

CREATE POLICY resident_buildings_read_own
  ON public.buildings FOR SELECT TO authenticated
  USING (private.is_resident_of_building(auth.uid(), id));

CREATE POLICY security_buildings_read_assigned
  ON public.buildings FOR SELECT TO authenticated
  USING (private.is_security_of_building(auth.uid(), id));

-- ---------------------------------------------------------------------------
-- units
-- ---------------------------------------------------------------------------
CREATE POLICY pmc_units_all
  ON public.units FOR ALL TO authenticated
  USING      ((auth.jwt() -> 'app_metadata' ->> 'role') = 'pmc')
  WITH CHECK ((auth.jwt() -> 'app_metadata' ->> 'role') = 'pmc');

CREATE POLICY resident_units_read_own
  ON public.units FOR SELECT TO authenticated
  USING (private.is_resident_of_unit(auth.uid(), id));

CREATE POLICY security_units_read_assigned_building
  ON public.units FOR SELECT TO authenticated
  USING (private.is_security_of_building(auth.uid(), building_id));

-- ---------------------------------------------------------------------------
-- profiles
-- ---------------------------------------------------------------------------
CREATE POLICY pmc_profiles_all
  ON public.profiles FOR ALL TO authenticated
  USING      ((auth.jwt() -> 'app_metadata' ->> 'role') = 'pmc')
  WITH CHECK ((auth.jwt() -> 'app_metadata' ->> 'role') = 'pmc');

CREATE POLICY any_user_read_own_profile
  ON public.profiles FOR SELECT TO authenticated
  USING (id = auth.uid());

CREATE POLICY any_user_update_own_profile
  ON public.profiles FOR UPDATE TO authenticated
  USING (id = auth.uid()) WITH CHECK (id = auth.uid());

CREATE POLICY security_read_residents_in_building
  ON public.profiles FOR SELECT TO authenticated
  USING (private.security_can_see_resident(auth.uid(), id));

-- ---------------------------------------------------------------------------
-- resident_assignments
-- ---------------------------------------------------------------------------
CREATE POLICY pmc_resident_assignments_all
  ON public.resident_assignments FOR ALL TO authenticated
  USING      ((auth.jwt() -> 'app_metadata' ->> 'role') = 'pmc')
  WITH CHECK ((auth.jwt() -> 'app_metadata' ->> 'role') = 'pmc');

CREATE POLICY resident_read_own_assignment
  ON public.resident_assignments FOR SELECT TO authenticated
  USING (profile_id = auth.uid());

CREATE POLICY security_read_assignments_in_building
  ON public.resident_assignments FOR SELECT TO authenticated
  USING (private.is_security_of_building(auth.uid(), private.unit_building_id(unit_id)));

-- ---------------------------------------------------------------------------
-- security_assignments
-- ---------------------------------------------------------------------------
CREATE POLICY pmc_security_assignments_all
  ON public.security_assignments FOR ALL TO authenticated
  USING      ((auth.jwt() -> 'app_metadata' ->> 'role') = 'pmc')
  WITH CHECK ((auth.jwt() -> 'app_metadata' ->> 'role') = 'pmc');

CREATE POLICY security_read_own_assignment
  ON public.security_assignments FOR SELECT TO authenticated
  USING (profile_id = auth.uid());

-- ---------------------------------------------------------------------------
-- visits
-- ---------------------------------------------------------------------------
CREATE POLICY pmc_visits_all
  ON public.visits FOR ALL TO authenticated
  USING      ((auth.jwt() -> 'app_metadata' ->> 'role') = 'pmc')
  WITH CHECK ((auth.jwt() -> 'app_metadata' ->> 'role') = 'pmc');

CREATE POLICY resident_visits_read_own
  ON public.visits FOR SELECT TO authenticated
  USING (private.is_resident_of_unit(auth.uid(), unit_id));

CREATE POLICY resident_visits_insert_own
  ON public.visits FOR INSERT TO authenticated
  WITH CHECK (private.is_resident_of_unit(auth.uid(), unit_id));

CREATE POLICY resident_visits_update_own
  ON public.visits FOR UPDATE TO authenticated
  USING      (private.is_resident_of_unit(auth.uid(), unit_id))
  WITH CHECK (private.is_resident_of_unit(auth.uid(), unit_id));

CREATE POLICY security_visits_read_building
  ON public.visits FOR SELECT TO authenticated
  USING (private.is_security_of_building(auth.uid(), private.unit_building_id(unit_id)));

CREATE POLICY security_visits_update_building
  ON public.visits FOR UPDATE TO authenticated
  USING      (private.is_security_of_building(auth.uid(), private.unit_building_id(unit_id)))
  WITH CHECK (private.is_security_of_building(auth.uid(), private.unit_building_id(unit_id)));

-- ---------------------------------------------------------------------------
-- unit_attachments
-- ---------------------------------------------------------------------------
CREATE POLICY pmc_attachments_all
  ON public.unit_attachments FOR ALL TO authenticated
  USING      ((auth.jwt() -> 'app_metadata' ->> 'role') = 'pmc')
  WITH CHECK ((auth.jwt() -> 'app_metadata' ->> 'role') = 'pmc');

CREATE POLICY resident_attachments_read_own
  ON public.unit_attachments FOR SELECT TO authenticated
  USING (private.is_resident_of_unit(auth.uid(), unit_id));

CREATE POLICY security_attachments_read_building
  ON public.unit_attachments FOR SELECT TO authenticated
  USING (private.is_security_of_building(auth.uid(), private.unit_building_id(unit_id)));

-- ---------------------------------------------------------------------------
-- amenity_bookings
-- ---------------------------------------------------------------------------
CREATE POLICY pmc_amenity_all
  ON public.amenity_bookings FOR ALL TO authenticated
  USING      ((auth.jwt() -> 'app_metadata' ->> 'role') = 'pmc')
  WITH CHECK ((auth.jwt() -> 'app_metadata' ->> 'role') = 'pmc');

CREATE POLICY resident_amenity_read_building
  ON public.amenity_bookings FOR SELECT TO authenticated
